export function translateUserFaq<T extends { question: string; answer: string; category: string }>(faq: T, language: UserLanguage): T {
  const key = seededFaqKeys[faq.question];
  const translated = key ? faqTranslations[language][key] : undefined;
  return translated ? { ...faq, ...translated } : faq;
}

function normalizeLanguage(value: string | undefined): UserLanguage {
  if (value?.toLowerCase().startsWith('en')) return 'en';
  if (value?.toLowerCase().startsWith('zh')) return 'zh';
  if (value?.toLowerCase().startsWith('ko')) return 'ko';
  return 'ja';
}

function detectBrowserLanguage(): UserLanguage {
  if (typeof navigator === 'undefined') return 'ja';
  return normalizeLanguage(navigator.languages?.[0] ?? navigator.language);
}

function getInitialLanguage(): UserLanguage {
  if (typeof window === 'undefined') return 'ja';
  try {
    const saved = window.localStorage?.getItem(LANGUAGE_STORAGE_KEY);
    return saved ? normalizeLanguage(saved) : detectBrowserLanguage();
  } catch {
    return detectBrowserLanguage();
  }
}

if (!i18n.isInitialized) {
  // Keep the server and first client render in the same language. The saved
  // language is applied immediately after hydration in useUserI18n below.
  void i18n.use(initReactI18next).init({ resources, lng: 'ja', fallbackLng: 'ja', interpolation: { escapeValue: false }, react: { useSuspense: false } });
}

