export function useUserI18n() {
  const { t, i18n: instance } = useTranslation();
  const language = normalizeLanguage(instance.resolvedLanguage ?? instance.language);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const next = getInitialLanguage();
    if (normalizeLanguage(instance.resolvedLanguage ?? instance.language) !== next) void instance.changeLanguage(next);
  }, [instance]);

  useEffect(() => {
    if (typeof document !== 'undefined') document.documentElement.lang = LANGUAGE_TAGS[language];
  }, [language]);

  function setLanguage(next: UserLanguage) {
    try { if (typeof window !== 'undefined') window.localStorage?.setItem(LANGUAGE_STORAGE_KEY, next); } catch { /* storage is unavailable in some private/shared browsers */ }
    void instance.changeLanguage(next);
  }

  return { t, language, setLanguage };
}

