type UserHeaderProps = { brand: string; brandHref: string; faqHref: string; adminHref?: string; brandAria?: string; statusHref?: string };

export function UserHeader({ brand, brandHref, faqHref, adminHref = '/admin', brandAria, statusHref = '/questions' }: UserHeaderProps) {
  const { t, language, setLanguage } = useUserI18n();
  const [open, setOpen] = useState(false);
  const selected = USER_LANGUAGE_OPTIONS.find((option) => option.value === language)?.label ?? '日本語';
  return <header className="reception-header user-header">
    <Link className="brand" href={brandHref} aria-label={brandAria ?? brand}>{brand}</Link>
    <div className="reception-header-tools"><nav aria-label={t('navigation.issues')}><Link href={brandHref}>{t('navigation.issues')}</Link><a href={faqHref}>{t('navigation.faq')}</a><Link href={statusHref}>{t('navigation.status')}</Link><Link className="reception-admin-link" href={adminHref}>{t('navigation.admin')}</Link></nav><div className="reception-language-picker"><button className="reception-language-trigger" type="button" aria-label={`${t('navigation.languageAria')}: ${selected}`} aria-expanded={open} aria-controls="user-language-menu" onClick={() => setOpen((current) => !current)}><span aria-hidden="true">🌐</span><span>{selected}</span><span aria-hidden="true">⌄</span></button>{open && <div className="reception-language-menu" id="user-language-menu" role="menu" aria-label={t('navigation.language')}>{USER_LANGUAGE_OPTIONS.map((option) => <button type="button" role="menuitemradio" aria-checked={language === option.value} className={language === option.value ? 'selected' : ''} key={option.value} onClick={() => { setLanguage(option.value); setOpen(false); }}>{option.label}<span aria-hidden="true">{language === option.value ? '✓' : ''}</span></button>)}</div>}</div></div>
  </header>;
}
